#pragma once

#include "core/Result.hpp"

#include "libslic3r/GCode/GCodeProcessor.hpp"
#include "libslic3r/Model.hpp"

#include <cstdint>
#include <string>

namespace Slic3r { namespace Bench {

// A G-code file's FNV-1a hash and size, both without the header's "; generated by" line, whose local
// time differs between passes and whose version differs between builds.
struct GCodeDigest
{
    std::uint64_t hash  = 0;
    std::uint64_t bytes = 0;
};

// Reads the file at `path`, in UTF-8, a line at a time. Throws std::runtime_error when it cannot be read.
GCodeDigest gcode_digest(const std::string& path);

// FNV-1a over each part's vertices, triangles and placement and each instance's placement, so the names and
// settings a file carries do not count.
std::uint64_t model_hash(const Model& model);

// The extrusion and travel moves the G-code processor read, its layers, the extruded volume and the
// G-code's size, with the moves and volume of each extrusion role in the metrics.
WorkStats work_of(const GCodeProcessorResult& result, std::uint64_t gcode_bytes);

}} // namespace Slic3r::Bench
